/*
 * Runs every suite of the C core's tests and prints one TAP line per test.
 * An optional argument runs only the tests whose name starts with it. With
 * EVOLU_TEST_SOFTWARE_CRYPTO set, the crypto layer uses only its software
 * path. SQLite allocates through sqlite_allocator.h's allocator. The exit
 * status is 1 when a test failed or none ran. run_suites is generated by
 * scripts/build.mts from the test file names.
 */
#include "test.h"

#include "evolu_crypto.h"
#include "sqlite3.h"
#include "sqlite_allocator.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// The tests rely on AddressSanitizer and UndefinedBehaviorSanitizer to fail
// on memory errors and undefined behavior.
#if defined(__has_feature)
#if !__has_feature(address_sanitizer)
#error "The C runner must be built with AddressSanitizer."
#endif
#if !__has_feature(undefined_behavior_sanitizer)
#error "The C runner must be built with UndefinedBehaviorSanitizer."
#endif
#endif

void run_suites(void);

static const char *filter = NULL;
static int test_count = 0;
static int failure_count = 0;
static int current_failed = 0;

void test_run(const char *name, void (*test)(void)) {
  if (filter != NULL && strncmp(name, filter, strlen(filter)) != 0) return;
  current_failed = 0;
  test();
  test_count++;
  if (current_failed) failure_count++;
  printf("%s %d - %s\n", current_failed ? "not ok" : "ok", test_count, name);
  fflush(stdout);
}

void test_fail(const char *file, int line, const char *message) {
  current_failed = 1;
  printf("# %s:%d: %s\n", file, line, message);
}

int test_bytes_equal(const void *a, const void *b, size_t length) {
  return memcmp(a, b, length) == 0;
}

int test_strings_equal(const char *a, const char *b) {
  return a != NULL && b != NULL && strcmp(a, b) == 0;
}

int main(int argc, char **argv) {
  if (argc > 1) filter = argv[1];
  // Before anything initializes SQLite, which keeps its allocator from then.
  if (test_install_sqlite_allocator() != SQLITE_OK) {
    printf("# SQLite refused the test allocator\n");
    return 1;
  }
  // CI runs the suite again on the software crypto path, which the output
  // says, so a run can't silently stay on the hardware one. It keeps DIT, as
  // a CPU with DIT but without the AES and SHA-512 instructions does, so the
  // DIT tests check the software path too. The CPU's features, which decide
  // the hardware paths it can run, follow.
  int cpu = evolu_crypto_hardware();
  int is_software = getenv("EVOLU_TEST_SOFTWARE_CRYPTO") != NULL;
  if (is_software) evolu_crypto_set_hardware(EVOLU_CRYPTO_DIT);
  printf("# crypto: %s\n# cpu: %d\n", is_software ? "software" : "hardware",
         cpu);

  run_suites();

  printf("1..%d\n# %d failed\n", test_count, failure_count);
  return failure_count > 0 || test_count == 0 ? 1 : 0;
}
